<script setup lang="ts">
import {computed} from 'vue';import {usePlatform} from '../stores/platform';import {apiMode} from '../api/client';import {filterRows,dataTypes} from '../domain';import type {Field} from '../domain';import QueryForm from '../components/QueryForm.vue';import DataTable from '../components/DataTable.vue';
const p=usePlatform();const scope=computed(()=>( {'场所管理':'sites','设备管理':'devices','角色管理':'roles','用户管理':'users'} as Record<string,'sites'|'devices'|'roles'|'users'>)[p.active]||'sites');
const fields=computed<Field[]>(()=>scope.value==='sites'?[{key:'name',label:'场所名称'},{key:'region',label:'区域',options:['全部',...p.db.sites.map(s=>s.region)]}]:scope.value==='devices'?[{key:'site',label:'所属场所',options:['全部',...p.visibleSites.map(s=>s.name)]},{key:'keyword',label:'设备名称 / 序列号'},{key:'status',label:'状态',options:['全部','在线','离线']},{key:'type',label:'设备分类',options:['全部',...dataTypes]}]:scope.value==='roles'?[{key:'id',label:'角色编号'},{key:'name',label:'角色名称'}]:[{key:'id',label:'用户编号'},{key:'name',label:'用户名称'},{key:'account',label:'登录账号'}]);
const columns=computed(()=>scope.value==='sites'?[{key:'name',label:'场所名称',link:true},{key:'region',label:'区域'},{key:'address',label:'地址'},{key:'deviceCount',label:'设备数量'}]:scope.value==='devices'?[{key:'name',label:'设备名称',link:true},{key:'serial',label:'序列号'},{key:'site',label:'所属场所'},{key:'type',label:'分类'},{key:'status',label:'状态'}]:scope.value==='roles'?[{key:'code',label:'角色编号',link:true},{key:'name',label:'角色名称'},{key:'menus',label:'菜单权限'},{key:'sites',label:'场所权限'},{key:'secretLabel',label:'属性'}]:[{key:'code',label:'用户编号',link:true},{key:'name',label:'用户名称'},{key:'account',label:'登录账号'},{key:'roleLabel',label:'角色'},{key:'enabledLabel',label:'启用状态'}]);
const rows=computed(()=>{const source:Record<string,unknown>[]=scope.value==='sites'?p.visibleSites.map(s=>({...s,deviceCount:p.db.devices.filter(d=>d.site===s.name).length})):scope.value==='devices'?p.db.devices.filter(d=>apiMode==='http'||p.superuser||p.visibleSites.some(s=>s.name===d.site)):scope.value==='roles'?p.db.roles.map(r=>({...r,code:r.code||r.id,secretLabel:r.secret?'涉密':'非涉密'})):p.db.users.map(u=>({...u,code:u.code||u.id,roleLabel:p.db.roles.find(r=>r.id===u.role)?.name,enabledLabel:u.enabled?'启用':'禁用'}));return p.filterRows(source,p.f,Object.fromEntries(fields.value.map(field=>[field.key,(r:Record<string,unknown>)=>field.key==='keyword'?String(r.name)+' '+String(r.serial):r[field.key]]))).filter(r=>!Array.isArray(p.f.ids)||p.f.ids.includes(String(r.id)));});
function open(row:Record<string,unknown>){if(scope.value==='sites')p.navigate('设备管理',{site:String(row.name)});else if(scope.value==='devices')p.deviceInfo(String(row.id));else p.formAdmin(scope.value,String(row.id));}
async function resetDevices(){await p.resetDevices(p.chosen.map(row=>String(row.id)));}
</script>
<template><QueryForm :fields="fields" :model="p.f" :label="scope==='roles'?'搜索':'查询'" @search="p.query" @reset="p.reset"/><div class="actions"><el-button type="primary" @click="p.formAdmin(scope)">新增</el-button><el-button @click="p.remove(scope)">删除</el-button><el-button v-if="scope==='devices'" @click="resetDevices">复位</el-button></div><DataTable :rows="rows" :columns="columns" @select="p.chosen=$event" @open="open"><template #rowActions="{row}"><el-button size="small" link type="primary" @click="p.formAdmin(scope,String(row.id))">编辑</el-button><template v-if="scope==='devices'"><el-button v-for="action in ['参数','离线记录','历史记录','导入','导出']" :key="action" size="small" link type="primary" @click="p.deviceOperation(String(row.id),action)">{{action}}</el-button></template></template></DataTable></template>



